// Get the leads array from the input
const leads = $input.item.json.leads;

// Filter: Only keep leads with email
const withEmail = leads.filter(item => {
  const email = item.json.Email;
  return email && email.trim().length > 0;
});

// Return filtered leads
return withEmail;

// ========================================
// REGEX EMAIL VALIDATION
// Fast filter to catch obviously invalid emails
// Handles multiple emails per lead (comma/semicolon separated)
// ========================================

const items = $input.all();
const validEmails = [];
const invalidEmails = [];

// Comprehensive email regex (RFC 5322 compliant)
const emailRegex = /^[a-zA-Z0-9.!#$%&'*+\/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/;

// Common invalid patterns
const invalidPatterns = [
  /noreply/i,
  /no-reply/i,
  /donotreply/i,
  /hello@/i,
  /test@/i,
  /example@/i
];

function validateEmail(email) {
  const cleanEmail = email.trim().toLowerCase();

  const isValidFormat = emailRegex.test(cleanEmail) &&
                       cleanEmail.length <= 254 &&
                       !cleanEmail.includes('..') &&
                       !cleanEmail.startsWith('.') &&
                       !cleanEmail.endsWith('.');

  if (!isValidFormat) {
    return { valid: false, reason: 'Invalid email format' };
  }

  const hasInvalidPattern = invalidPatterns.some(pattern => pattern.test(cleanEmail));

  if (hasInvalidPattern) {
    return { valid: false, reason: 'Generic or no-reply email address' };
  }

  return { valid: true, email: cleanEmail };
}

for (const item of items) {
  const emailField = item.json.Email;

  if (!emailField) {
    invalidEmails.push({
      json: {
        ...item.json,
        validation_status: 'no_email',
        validation_stage: 'regex',
        rejection_reason: 'No email provided'
      }
    });
    continue;
  }

  const emailList = emailField.split(/[,;]+/).map(e => e.trim()).filter(e => e.length > 0);

  const validatedEmails = [];
  const rejectedEmails = [];

  for (const email of emailList) {
    const result = validateEmail(email);

    if (result.valid) {
      validatedEmails.push(result.email);
    } else {
      rejectedEmails.push({ email, reason: result.reason });
    }
  }

  if (validatedEmails.length > 0) {
    validEmails.push({
      json: {
        ...item.json,
        Email: validatedEmails.join(', '),
        validation_stage: 'regex_passed',
        emails_kept: validatedEmails.length,
        emails_removed: rejectedEmails.length,
        removed_emails: rejectedEmails.map(r => r.email).join(', ') || 'none'
      }
    });
  } else {
    invalidEmails.push({
      json: {
        ...item.json,
        validation_status: 'all_emails_invalid',
        validation_stage: 'regex',
        rejection_reason: `All ${rejectedEmails.length} email(s) failed validation`,
        rejected_details: rejectedEmails.map(r => `${r.email} (${r.reason})`).join('; ')
      }
    });
  }
}

console.log(`Regex Validation: ${validEmails.length} leads passed, ${invalidEmails.length} failed`);

return validEmails;

// ========================================
// SIMPLIFIED DOMAIN VALIDATION
// Skip DNS check, only filter disposable domains
// ========================================

const items = $input.all();
const validDomains = [];

const disposableDomains = [
  'tempmail.com', 'guerrillamail.com', 'mailinator.com',
  '10minutemail.com', 'throwaway.email', 'maildrop.cc',
  'temp-mail.org', 'getnada.com', 'trashmail.com',
  'yopmail.com', 'sharklasers.com', 'guerrillamail.info'
];

for (const item of items) {
  const emailField = item.json.Email;
  const firstEmail = emailField.split(/[,;]+/)[0].trim();
  const domain = firstEmail.split('@')[1].toLowerCase();

  if (!disposableDomains.includes(domain)) {
    validDomains.push(item);
  }
}

console.log(`Domain Check: ${validDomains.length} passed`);
return validDomains;

// ========================================
// DNS/MX RECORD CHECK VIA GOOGLE DoH
// Checks if the email domain actually has mail servers
// Uses domain caching to avoid duplicate lookups
// ========================================

const items = $input.all();
const validItems = [];
const invalidItems = [];

// Cache: check each unique domain only once
const domainCache = {};

async function checkMX(domain) {
  if (domainCache[domain] !== undefined) {
    return domainCache[domain];
  }

  try {
    const response = await fetch(
      `https://dns.google/resolve?name=${encodeURIComponent(domain)}&type=MX`
    );
    const data = await response.json();

    // Status 0 = NOERROR, Answer array with MX records
    const hasMX = data.Status === 0 && data.Answer && data.Answer.length > 0;

    domainCache[domain] = {
      valid: hasMX,
      mx_server: hasMX ? data.Answer[0].data : null,
      reason: hasMX ? 'MX records found' : 'No MX records - domain cannot receive email'
    };
  } catch (error) {
    // If DNS lookup fails, give benefit of doubt
    domainCache[domain] = {
      valid: true,
      mx_server: null,
      reason: 'DNS lookup failed - assuming valid'
    };
  }

  return domainCache[domain];
}

// Process all items
for (const item of items) {
  const emailField = item.json.Email;
  if (!emailField) continue;

  const firstEmail = emailField.split(/[,;]+/)[0].trim();
  const domain = firstEmail.split('@')[1]?.toLowerCase();

  if (!domain) {
    invalidItems.push({
      json: { ...item.json, mx_status: 'invalid', mx_reason: 'No domain found' }
    });
    continue;
  }

  const result = await checkMX(domain);

  if (result.valid) {
    validItems.push({
      json: {
        ...item.json,
        mx_status: 'valid',
        mx_server: result.mx_server,
        mx_reason: result.reason,
        validation_stage: 'dns_passed'
      }
    });
  } else {
    invalidItems.push({
      json: {
        ...item.json,
        mx_status: 'invalid',
        mx_reason: result.reason,
        validation_stage: 'dns_failed'
      }
    });
  }
}

console.log(`DNS/MX Check: ${validItems.length} passed, ${invalidItems.length} failed (${Object.keys(domainCache).length} unique domains checked)`);

return validItems;

// ========================================
// PROCESS AI RESPONSE
// Parse Claude's analysis and categorize leads
// ========================================

const items = $input.all();
const highQuality = [];
const mediumQuality = [];
const lowQuality = [];
const failed = [];

for (const item of items) {
  try {
    const content = item.json.content;

    if (!content || !Array.isArray(content) || content.length === 0) {
      throw new Error('Invalid response format from AI');
    }

    const textContent = content.find(c => c.type === 'text');
    if (!textContent || !textContent.text) {
      throw new Error('No text content in AI response');
    }

    let aiResponse = textContent.text.trim();
    aiResponse = aiResponse.replace(/```json\s*/g, '').replace(/```\s*/g, '');

    const analysis = JSON.parse(aiResponse);

    const originalData = item.json.inputData || item.json;

    const enrichedLead = {
      json: {
        ...originalData,
        ai_quality_score: analysis.quality_score || 5,
        ai_reasoning: analysis.reasoning || 'No reasoning provided',
        send_recommendation: analysis.send_recommendation || 'maybe',
        personalization_tips: analysis.personalization_tips || '',
        red_flags: analysis.red_flags || [],
        confidence: analysis.confidence || 'medium',
        validation_stage: 'ai_complete',
        timestamp: new Date().toISOString()
      }
    };

    const score = analysis.quality_score || 5;
    const recommendation = (analysis.send_recommendation || 'maybe').toLowerCase();

    if (score >= 7 && (recommendation === 'yes' || recommendation === 'maybe')) {
      highQuality.push(enrichedLead);
    } else if (score >= 4 && score < 7) {
      mediumQuality.push(enrichedLead);
    } else {
      lowQuality.push(enrichedLead);
    }

  } catch (error) {
    console.error('AI Response Parsing Error:', error.message);

    failed.push({
      json: {
        ...item.json,
        ai_quality_score: 0,
        ai_reasoning: 'AI analysis failed: ' + error.message,
        send_recommendation: 'no',
        validation_status: 'ai_failed',
        validation_stage: 'ai_error',
        error_details: error.message
      }
    });
  }
}

console.log(`AI Analysis: ${highQuality.length} high quality, ${mediumQuality.length} medium, ${lowQuality.length} low, ${failed.length} failed`);

return highQuality;

// ========================================
// GENERATE PERSONALIZED EMAIL
// Create email content using AI insights
// ========================================

const items = $input.all();
const emails = [];

for (const item of items) {
  const lead = item.json;

  const businessName = lead["Business Name"] || "there";
  const firstName = businessName.split(' ')[0];
  const category = lead.Category || "your business";
  const location = lead.City ? `${lead.City}, ${lead.Country}` : lead.Country;
  const personalizationTips = lead.personalization_tips || "";

  const subjectLines = [
    `Quick question about ${businessName}`,
    `Idea for ${businessName}'s ${category}`,
    `${firstName}, thought you'd find this interesting`,
    `Growing ${businessName} in ${location}`
  ];

  const subject = subjectLines[Math.floor(Math.random() * subjectLines.length)];

  const emailBody = `Hi ${firstName},

I came across ${businessName} and was impressed by your work in ${category}.

${personalizationTips ? personalizationTips + '\n\n' : ''}I wanted to reach out because we've been helping similar businesses in ${location} [YOUR VALUE PROPOSITION HERE].

Would you be open to a quick 15-minute call next week to explore how we might help ${businessName}?

Best regards,
[YOUR NAME]
[YOUR COMPANY]
[YOUR CONTACT INFO]`;

  emails.push({
    json: {
      ...lead,
      email_subject: subject,
      email_body: emailBody,
      ready_to_send: true,
      generated_at: new Date().toISOString()
    }
  });
}

return emails;

// ========================================
// LOG RESULTS
// Track success/failure for analytics
// ========================================

const items = $input.all();
const results = [];

for (const item of items) {
  const lead = item.json;

  const status = item.error ? 'failed' : 'sent';
  const errorMessage = item.error ? item.error.message : null;

  results.push({
    json: {
      email: lead.Email,
      business_name: lead["Business Name"],
      status: status,
      error_message: errorMessage,
      ai_quality_score: lead.ai_quality_score,
      sent_at: new Date().toISOString(),
      subject: lead.email_subject,
      campaign_id: 'cold-email-' + new Date().toISOString().split('T')[0]
    }
  });
}

console.log(`Email Campaign: ${results.filter(r => r.json.status === 'sent').length} sent, ${results.filter(r => r.json.status === 'failed').length} failed`);

return results;

