// Get the caption from Telegram Trigger
const caption = $('Telegram Trigger').first().json.message.caption || '';

// Regex to extract email (standard email pattern)
const emailRegex = /[\w.-]+@[\w.-]+\.\w+/;
const emailMatch = caption.match(emailRegex);

// Regex to extract workflow name (pattern: word_word, can have multiple underscores)
// This looks for words connected by underscores (like secret_formula, epstien_formula, hello_world)
const workflowRegex = /\b[a-zA-Z0-9]+_[a-zA-Z0-9_]+\b/;
const workflowMatch = caption.match(workflowRegex);

// Return the extracted data
return [{
  json: {
    extracted_email: emailMatch ? emailMatch[0] : null,
    workflow_name: workflowMatch ? workflowMatch[0] : null,
    original_caption: caption,
    // Include a flag to check if both were found
    has_email: !!emailMatch,
    has_workflow: !!workflowMatch
  }
}];
